-- Batch for Class 4 (30 questions)
INSERT INTO public.scenarios (
  scenario_code, class_level, developmental_band, competency, difficulty,
  prompt, options, learning_objective, hint, irt_a, irt_b, irt_c,
  international_benchmark, is_active
) VALUES
  ('C04-SCI-01', 4, '3-4', 'scientificInquiry', 'standard', 'A student places two identical potted plants in identical soil. Plant A receives 100 mL of water in direct sunlight daily; Plant B receives 100 mL of water in a completely dark closet. After two weeks, Plant B has turned pale yellow and stretched unusually tall and thin. What does this experiment demonstrate?', '[{"text":"Plants need sunlight to synthesize chlorophyll and produce food through photosynthesis.","correct":true},{"text":"Plants grow healthier without light because darkness accelerates stem strength.","correct":false},{"text":"Water evaporates faster in darkness, suffocating the roots.","correct":false},{"text":"Sunlight prevents plant cells from dividing.","correct":false}]'::jsonb, 'Photosynthesis light dependency and etiolation.', 'Think about why chlorophyll gives plants their green color.', 1.4, -0.3999999999999999, 0.25, 'Singapore Primary Science Syllabus', true),
  ('C04-SCI-02', 4, '3-4', 'scientificInquiry', 'standard', 'Three identical liquid samples (A, B, and C) are poured into a clear graduated cylinder. Layer A sits at the bottom, Layer B floats in the middle, and Layer C floats on top. If a solid plastic bead with density 1.1 g/cm³ is dropped in, and it sinks through Layer C but floats on top of Layer B, what can you infer?', '[{"text":"Density of C < 1.1 g/cm³ < Density of B < Density of A.","correct":true},{"text":"Layer C has the greatest density because it is at the top.","correct":false},{"text":"The plastic bead dissolves the middle layer.","correct":false},{"text":"All three liquids have equal density because they are in the same cylinder.","correct":false}]'::jsonb, 'Fluid density layering / Joule heating & power dissipation / Quantum photoelectric energy threshold analysis.', 'Objects float in liquids that are more dense than themselves.', 1.3, -0.12, 0.25, 'Singapore PSLE Science', true),
  ('C04-SCI-03', 4, '3-4', 'scientificInquiry', 'advanced', 'An experimenter drops a metal ball from heights of 1m, 2m, and 3m onto soft clay. The depth of the crater in the clay is 4mm, 8mm, and 12mm respectively. What is the independent variable and what physical quantity does crater depth measure?', '[{"text":"Independent variable: drop height; crater depth measures kinetic energy transferred to the clay.","correct":true},{"text":"Independent variable: crater depth; measured quantity is gravity.","correct":false},{"text":"Independent variable: clay softness; measured quantity is time.","correct":false},{"text":"Independent variable: ball mass; measured quantity is air friction.","correct":false}]'::jsonb, 'Identify experimental variables / Redox electrochemistry / Parallel nuclear decay kinematics.', 'The independent variable is what the experimenter intentionally manipulates.', 1.4, 0.6000000000000001, 0.25, 'US NGSS Middle School PS3', true),
  ('C04-SCI-04', 4, '3-4', 'scientificInquiry', 'advanced', 'An optical bench tests refraction of light rays passing from medium 1 (index $n_1$) into medium 2 (index $n_2$). If the angle of incidence is $\theta_1 = 30^\circ$ and the refracted ray bends toward the normal line with $\theta_2 = 19.5^\circ$, what can be deduced about the optical density and wave speed?', '[{"text":"Medium 2 is optically denser ($n_2 > n_1$), and light propagates slower in medium 2 ($v_2 < v_1$).","correct":true},{"text":"Medium 2 is less dense, and light speed increases.","correct":false},{"text":"Light undergoes total internal reflection.","correct":false},{"text":"Light frequency decreases while wavelength remains constant.","correct":false}]'::jsonb, 'Snell’s Law, wave speed variance across refractive boundaries, and wave mechanics.', 'Bending toward the normal means light slows down.', 1.5, 0.8, 0.25, 'Cambridge IGCSE / Singapore O-Level Physics', true),
  ('C04-SCI-05', 4, '3-4', 'scientificInquiry', 'olympiad', 'Two pendulums have string lengths of 25 cm and 100 cm with identical bobs. If the 25 cm pendulum completes 20 full oscillations in 20 seconds, how many full oscillations will the 100 cm pendulum complete in the same 20 seconds?', '[{"text":"10 oscillations, because pendulum period is proportional to $\\sqrt{L}$, so doubling the period halves the frequency.","correct":true},{"text":"5 oscillations, because length is 4 times longer.","correct":false},{"text":"20 oscillations, because mass is identical.","correct":false},{"text":"40 oscillations, because longer strings swing faster.","correct":false}]'::jsonb, 'Non-linear proportionality in physical laws ($T \propto \sqrt{L}$ or $v_{\text{rms}} \propto \sqrt{T}$).', 'Notice the square root relationship.', 1.7, 1.28, 0.25, 'Chinese National Physics Olympiad / SASMO Junior', true),
  ('C04-SCI-06', 4, '3-4', 'scientificInquiry', 'olympiad', 'In a double-slit interference experiment with slit separation $d$ and screen distance $D$, light of wavelength $\lambda$ creates bright fringe spacing $\Delta y = \frac{\lambda D}{d}$. If the entire apparatus is immersed in water (refractive index $n = 1.33$), what happens to the fringe spacing?', '[{"text":"Fringe spacing decreases by a factor of 1.33 because the wavelength in water is $\\lambda / n$.","correct":true},{"text":"Fringe spacing increases by 1.33 because light speed decreases.","correct":false},{"text":"Fringes disappear completely due to total internal reflection.","correct":false},{"text":"Fringe spacing remains unchanged because frequency remains constant.","correct":false}]'::jsonb, 'Wave optics, wavelength reduction in refractive dielectric media, and interference fringe scaling.', 'In a medium with index n, speed and wavelength shrink by factor n, but frequency does not change.', 1.8, 1.5, 0.25, 'International Physics Olympiad (IPhO) / China Gaokao Physics', true),
  ('C04-CT-01', 4, '3-4', 'computationalThinking', 'standard', 'A rover on Mars receives a sequence of movement commands: [FORWARD 3, TURN_LEFT 90, FORWARD 2, TURN_RIGHT 90, BACKWARD 3]. What is the net straight-line displacement of the rover from its starting location?', '[{"text":"2 units to the left of the original position.","correct":true},{"text":"6 units forward.","correct":false},{"text":"Back at the exact starting location.","correct":false},{"text":"8 units diagonally.","correct":false}]'::jsonb, 'Coordinate tracking / Linear search worst-case analysis / Recursive state computation.', 'Follow the steps one by one.', 1.3, -0.31999999999999995, 0.25, 'European Bebras Challenge', true),
  ('C04-CT-02', 4, '3-4', 'computationalThinking', 'standard', 'A stack data structure follows Last-In, First-Out (LIFO). The operations executed are: PUSH(5), PUSH(8), PUSH(3), POP(), PUSH(12), POP(). What number is currently on the top of the stack?', '[{"text":"8","correct":true},{"text":"5","correct":false},{"text":"12","correct":false},{"text":"3","correct":false}]'::jsonb, 'Stack LIFO state transitions and memory frame tracking.', 'POP removes the item that was added most recently.', 1.4, 0, 0.25, 'Bebras Computational Challenge / AP CS Principles', true),
  ('C04-CT-03', 4, '3-4', 'computationalThinking', 'advanced', 'You want to find an odd number between 1 and 100. Each question you ask can only be answered YES or NO. By always asking whether the number is greater than the middle of the remaining range, what is the maximum number of questions needed to find the exact number?', '[{"text":"6 questions, because $2^5 = 32 < 50 < 2^6 = 64$.","correct":true},{"text":"25 questions.","correct":false},{"text":"50 questions.","correct":false},{"text":"10 questions.","correct":false}]'::jsonb, 'Binary decision tree depth / Spanning tree edge minimization in graph theory.', 'Think about the minimum connections needed to prevent any node from being disconnected.', 1.5, 0.62, 0.25, 'Bebras Intermediate / Singapore Computing', true),
  ('C04-CT-04', 4, '3-4', 'computationalThinking', 'advanced', 'In sorting algorithms, what distinguishes Bubble Sort ($O(n^2)$ average) from Merge Sort ($O(n \log n)$ average) on large lists of 100,000 items?', '[{"text":"Merge Sort uses divide-and-conquer recursion, executing in thousands of operations rather than billions.","correct":true},{"text":"Bubble Sort is faster because it does not require additional memory.","correct":false},{"text":"Both run in identical time because both compare elements in pairs.","correct":false},{"text":"Merge Sort only works on numbers, whereas Bubble Sort works on words.","correct":false}]'::jsonb, 'Asymptotic algorithmic growth rates ($O(n^2)$ vs $O(n \log n)$) at scale.', 'Calculate $(100,000)^2 = 10,000,000,000$ operations versus $100,000 \times 17 \approx 1,700,000$.', 1.6, 0.9600000000000001, 0.25, 'USACO Bronze / Oxford Computing Challenge', true),
  ('C04-CT-05', 4, '3-4', 'computationalThinking', 'olympiad', 'A dynamic programming table solves the 0/1 Knapsack problem with capacity $W$ and $N$ items. If an iterative table stores state $dp[i][w]$, what does each cell value represent?', '[{"text":"The maximum achievable value using a subset of the first $i$ items with total weight at most $w$.","correct":true},{"text":"The remaining weight capacity after packing item $i$.","correct":false},{"text":"The total number of items included in the knapsack so far.","correct":false},{"text":"The ratio of value to weight for item $i$.","correct":false}]'::jsonb, 'Subproblem optimal substructure in Dynamic Programming.', 'The state stores the optimal objective value for a constrained capacity subproblem.', 1.8, 1.38, 0.25, 'International Olympiad in Informatics (IOI) / USACO Silver', true),
  ('C04-CT-06', 4, '3-4', 'computationalThinking', 'olympiad', 'A hash function maps keys into an array of size $M$. If two distinct keys $k_1 \ne k_2$ produce $h(k_1) = h(k_2)$, this is called a collision. Which strategy provides $O(1)$ expected lookup by appending colliding items to a linked list at that index?', '[{"text":"Separate Chaining","correct":true},{"text":"Linear Probing","correct":false},{"text":"Quadratic Probing","correct":false},{"text":"Double Hashing","correct":false}]'::jsonb, 'Hash table collision resolution architectures.', 'Look for the term that implies linking items in chains outside the primary array.', 1.7, 1.4, 0.25, 'China National Olympiad in Informatics (NOIP) Senior', true),
  ('C04-ED-01', 4, '3-4', 'engineeringDesign', 'standard', 'A team builds a toy crane. When lifting a heavy block, the crane tips over forward. Which design change will balance the crane effectively without reducing the load weight?', '[{"text":"Add a counterweight to the back of the crane arm and widen the base.","correct":true},{"text":"Make the crane arm twice as long.","correct":false},{"text":"Use thinner string for the hook.","correct":false},{"text":"Paint the crane bright yellow.","correct":false}]'::jsonb, 'Torque balance & center of gravity / Structural geometric rigidity / Thermal expansion tolerance in aerospace.', 'Think of a seesaw: how do you balance a heavy person?', 1.3, -0.30000000000000004, 0.25, 'US NGSS Engineering Design / Project Lead The Way', true),
  ('C04-ED-02', 4, '3-4', 'engineeringDesign', 'standard', 'An engineer designs a solar-powered water pump for an off-grid farm. The pump requires 500W of power. If the solar panels have an efficiency of 20% and peak sunlight intensity is 1,000 W/m², what is the MINIMUM solar collector surface area required?', '[{"text":"2.5 square meters ($1000 \\times 0.20 = 200\\text{ W/m}^2$; $500 / 200 = 2.5\\text{ m}^2$).","correct":true},{"text":"1.0 square meters.","correct":false},{"text":"5.0 square meters.","correct":false},{"text":"10.0 square meters.","correct":false}]'::jsonb, 'Solar energy conversion efficiency and collector area sizing.', 'Calculate usable electrical power per square meter first.', 1.4, 0.12, 0.25, 'European Clean Energy Engineering Curriculum / NGSS HS-ETS1', true),
  ('C04-ED-03', 4, '3-4', 'engineeringDesign', 'advanced', 'A bicycle braking system uses hydraulic disc calipers. The master cylinder at the brake lever has a piston area of 1 cm², while the slave caliper piston at the wheel has an area of 4 cm². If the rider applies a force of 50 N to the master cylinder, what clamping force does the slave cylinder exert on the brake rotor (assuming no fluid friction)?', '[{"text":"200 N, because Pascal''s Principle transmits equal pressure: $F_2 = F_1 \\times (A_2 / A_1)$.","correct":true},{"text":"50 N, because force cannot multiply in closed fluids.","correct":false},{"text":"12.5 N, because area expanded.","correct":false},{"text":"800 N, because area is squared.","correct":false}]'::jsonb, 'Pascal’s Principle, hydraulic mechanical advantage, and fluid power transmission.', 'Pressure $P = F/A$ is uniform throughout the connected hydraulic fluid.', 1.5, 0.62, 0.25, 'German Dual Vocational Mechatronics / US Project Lead The Way', true),
  ('C04-ED-04', 4, '3-4', 'engineeringDesign', 'advanced', 'In autonomous electric vehicles, why do battery management systems (BMS) implement active cell balancing during charging cycles?', '[{"text":"To prevent individual cells with slightly lower capacity from overcharging or deep-discharging, which causes thermal runaway and premature pack degradation.","correct":true},{"text":"To make the vehicle accelerate twice as fast at low battery levels.","correct":false},{"text":"To convert alternating current directly into radio signals.","correct":false},{"text":"To eliminate the need for an electric motor.","correct":false}]'::jsonb, 'Lithium-ion electrochemical cell degradation, thermal safety, and state-of-charge management.', 'A battery pack is only as strong as its weakest cell.', 1.6, 0.8999999999999999, 0.25, 'MIT Engineering NEET / Singapore A-Level Engineering Science', true),
  ('C04-ED-05', 4, '3-4', 'engineeringDesign', 'olympiad', 'A structural cantilever beam of length $L$ carries a concentrated end load $P$. If both the width $b$ and depth $h$ of its rectangular cross-section are doubled ($2b, 2h$), by what factor does the maximum tip deflection $\delta = \frac{PL^3}{3EI}$ decrease (where moment of inertia $I = \frac{bh^3}{12}$)?', '[{"text":"Deflection decreases by a factor of 16 (it becomes $1/16$ of original deflection).","correct":true},{"text":"Deflection decreases by a factor of 4.","correct":false},{"text":"Deflection decreases by a factor of 8.","correct":false},{"text":"Deflection decreases by a factor of 2.","correct":false}]'::jsonb, 'Beam deflection formulas, second moment of area, and structural scale geometry.', 'Calculate how $I = \frac{b h^3}{12}$ scales when $b \to 2b$ and $h \to 2h$: $I'' = (2b)(2h)^3 = 16 I$.', 1.8, 1.28, 0.25, 'China National Collegiate / Senior High Engineering Mechanics Challenge', true),
  ('C04-ED-06', 4, '3-4', 'engineeringDesign', 'olympiad', 'In designing an unmanned quadcopter drone, flight endurance is limited by the specific energy of the battery. If an engineer replaces a 1 kg lithium-ion battery (250 Wh/kg) with a 1 kg solid-state battery (500 Wh/kg), why does flight time MORE than double in real atmospheric conditions?', '[{"text":"The total payload mass remains identical, meaning aerodynamic hover power required remains constant while available energy doubles, enabling continuous optimal motor efficiency.","correct":true},{"text":"Solid-state batteries produce negative gravity.","correct":false},{"text":"Propellers spin at infinite velocity when powered by solid-state chemistry.","correct":false},{"text":"Air resistance drops to zero.","correct":false}]'::jsonb, 'Hover aerodynamics, power-to-weight endurance scaling, and battery specific energy limits.', 'Notice that the battery weight did not change, so the drone does not need extra lift power to stay aloft.', 1.8, 1.54, 0.25, 'FIRST Robotics World Championship / Singapore DSTA Engineering', true),
  ('C04-MR-01', 4, '3-4', 'mathematicalReasoning', 'standard', 'In a parking lot, there are 20 vehicles consisting of bicycles (2 wheels each) and cars (4 wheels each). If there are 64 wheels in total, how many cars are parked in the lot?', '[{"text":"12 cars (and 8 bicycles).","correct":true},{"text":"10 cars.","correct":false},{"text":"14 cars.","correct":false},{"text":"16 cars.","correct":false}]'::jsonb, 'Assumption heuristic / Difference of squares factorization / Logarithmic equations with domain constraints.', 'Assume all 20 vehicles were bicycles: that would be 40 wheels. Each car adds 2 extra wheels.', 1.4, -0.3999999999999999, 0.25, 'Singapore Math (Bar Models / Heuristics) / SASMO', true),
  ('C04-MR-02', 4, '3-4', 'mathematicalReasoning', 'standard', 'A circle of radius 6 cm is inscribed inside an equilateral triangle. What is the area of the equilateral triangle?', '[{"text":"$108\\sqrt{3}\\text{ cm}^2$","correct":true},{"text":"$72\\sqrt{3}\\text{ cm}^2$","correct":false},{"text":"$144\\text{ cm}^2$","correct":false},{"text":"$36\\pi\\text{ cm}^2$","correct":false}]'::jsonb, 'Incircle geometry of regular polygons and trigonometric relationship with altitude.', 'In an equilateral triangle, inradius $r = h/3$. If $r=6$, altitude $h=18$, side $s = 18 / (\sqrt{3}/2) = 12\sqrt{3}$.', 1.5, 0.28, 0.25, 'Kangaroo Math Student / AMC 8', true),
  ('C04-MR-03', 4, '3-4', 'mathematicalReasoning', 'advanced', 'How many three-digit positive integers are divisible by both 4 and 6?', '[{"text":"75 integers (multiples of $\\text{LCM}(4,6)=12$ between 100 and 999).","correct":true},{"text":"150 integers.","correct":false},{"text":"83 integers.","correct":false},{"text":"90 integers.","correct":false}]'::jsonb, 'LCM arithmetic arithmetic progression counting / Vieta’s formulas.', 'Use the relationship $(r_1 - r_2)^2 = (r_1 + r_2)^2 - 4r_1 r_2$.', 1.6, 0.74, 0.25, 'American Mathematics Competitions (AMC 8/10)', true),
  ('C04-MR-04', 4, '3-4', 'mathematicalReasoning', 'advanced', 'How many distinct permutations can be formed from the letters in the word ''PARALLEL''?', '[{"text":"3,360 permutations ($\\frac{8!}{3! \\times 2!} = \\frac{40,320}{6 \\times 2} = 3,360$).","correct":true},{"text":"40,320 permutations.","correct":false},{"text":"6,720 permutations.","correct":false},{"text":"1,680 permutations.","correct":false}]'::jsonb, 'Multinomial permutations with repeated elements.', 'Count the repetitions: 3 Ls, 2 As in an 8-letter word.', 1.6, 1, 0.25, 'China High School Mathematics League / AMC 10', true),
  ('C04-MR-05', 4, '3-4', 'mathematicalReasoning', 'olympiad', 'What is the remainder when $3^{2026}$ is divided by 7?', '[{"text":"2, because by Fermat''s Little Theorem $3^6 \\equiv 1 \\pmod 7$, and $2026 = 6 \\times 337 + 4$, so $3^4 = 81 \\equiv 4 \\pmod 7$ (or 2).","correct":true},{"text":"1","correct":false},{"text":"4","correct":false},{"text":"6","correct":false}]'::jsonb, 'Fermat’s Little Theorem and modular exponentiation cycles.', 'Compute the powers of 3 modulo 7: 3, 9=2, 6, 18=4, 12=5, 15=1 (cycle of length 6).', 1.8, 1.42, 0.25, 'Chinese Mathematical Olympiad (CMO) / Singapore SMO', true),
  ('C04-MR-06', 4, '3-4', 'mathematicalReasoning', 'olympiad', 'Consider the infinite geometric series $S = 1 + 2x + 3x^2 + 4x^3 + \dots$ for $|x| < 1$. What is the closed-form algebraic sum of this arithmetico-geometric series?', '[{"text":"$\\frac{1}{(1-x)^2}$","correct":true},{"text":"$\\frac{1}{1-x}$","correct":false},{"text":"$\\frac{x}{(1-x)^2}$","correct":false},{"text":"$\\frac{1}{1-x^2}$","correct":false}]'::jsonb, 'Summation of arithmetico-geometric series via perturbation or derivative of geometric series.', 'Notice that $\frac{d}{dx}\left(\frac{1}{1-x}\right) = \frac{d}{dx}(1+x+x^2+x^3+\dots) = 1+2x+3x^2+\dots$.', 1.8, 1.64, 0.25, 'Putnam / AMC 12 / IIT-JEE Advanced', true),
  ('C04-ST-01', 4, '3-4', 'systemsThinking', 'standard', 'In an agricultural valley, farmers spray a chemical that kills 95% of caterpillars eating cabbage. Six weeks later, cabbage yield is worse than before because the birds that ate caterpillars migrated away, and aphid pests (which caterpillars kept in check) multiplied unchecked. What systems principle does this illustrate?', '[{"text":"Unintended consequences in an interconnected ecosystem: eliminating one component triggers second-order cascades.","correct":true},{"text":"Pesticides make soil toxic to sunlight.","correct":false},{"text":"Birds eat cabbage directly when caterpillars are absent.","correct":false},{"text":"Caterpillars protect plants from rain.","correct":false}]'::jsonb, 'Second-order effects in ecological food webs / Resource contention in shared flow networks / Control loop phase margin & resonance.', 'Look beyond the immediate action to the downstream ripple effects.', 1.3, -0.24, 0.25, 'OECD PISA Systems Thinking Framework', true),
  ('C04-ST-02', 4, '3-4', 'systemsThinking', 'standard', 'A logistics company observes the ''Bullwhip Effect'': a small 5% spike in consumer retail demand for toilet paper causes a 15% order increase to wholesalers, and a 40% order surge to paper manufacturers. What is the root systemic cause of this amplification?', '[{"text":"Information distortion, safety-stock buffering, and lack of real-time supply chain transparency across sequential tiers.","correct":true},{"text":"Paper mills intentionally slow production to raise prices.","correct":false},{"text":"Trucks travel slower when carrying larger loads.","correct":false},{"text":"Consumers buy paper only on weekends.","correct":false}]'::jsonb, 'The Bullwhip Effect in multi-echelon supply networks and order variance propagation.', 'Each tier adds extra buffer stock because they cannot directly see final consumer demand.', 1.4, 0.21999999999999997, 0.25, 'MIT System Dynamics in K-12 / AP Macroeconomics', true),
  ('C04-ST-03', 4, '3-4', 'systemsThinking', 'advanced', 'In climate science, the ice-albedo feedback is a classic example of which systemic loop dynamic?', '[{"text":"A reinforcing (positive) feedback loop: warming melts reflective ice, revealing dark ocean that absorbs more heat and accelerates warming.","correct":true},{"text":"A balancing (negative) feedback loop that automatically cools the planet back to baseline.","correct":false},{"text":"An isolated thermodynamic open loop with zero feedback.","correct":false},{"text":"A linear cause-and-effect with static equilibrium.","correct":false}]'::jsonb, 'Reinforcing feedback mechanisms in non-linear planetary climate systems.', 'Does the effect amplify the original cause (positive) or counteract it (negative)?', 1.5, 0.64, 0.25, 'European Matura Environmental Systems / PISA 2025', true),
  ('C04-ST-04', 4, '3-4', 'systemsThinking', 'advanced', 'When a city adds 3 new highway lanes to relieve severe traffic congestion, commute times initially drop for 3 months, but return to severe gridlock 18 months later (Braess''s Paradox / Induced Demand). Why does expanding capacity fail to solve the congestion?', '[{"text":"Induced demand: reduced travel friction incentivizes public transit riders and distant commuters to drive, filling new capacity until congestion equilibrium restores.","correct":true},{"text":"Cars travel slower on wider highways due to optical illusions.","correct":false},{"text":"The city traffic lights automatically turn red more frequently.","correct":false},{"text":"Highway asphalt expands in sunlight, narrowing the lanes.","correct":false}]'::jsonb, 'Induced demand, feedback elasticity, and unintended policy equilibrium in urban transport networks.', 'Think about how lowering the perceived cost of an activity changes consumer behavior.', 1.6, 0.9600000000000001, 0.25, 'OECD Urban Mobility Systems / Harvard Policy Systems', true),
  ('C04-ST-05', 4, '3-4', 'systemsThinking', 'olympiad', 'In predator-prey dynamics modeled by the Lotka-Volterra differential equations ($\frac{dx}{dt} = \alpha x - \beta x y$, $\frac{dy}{dt} = \delta x y - \gamma y$), what phase relationship exists between prey population peaks ($x$) and predator population peaks ($y$)?', '[{"text":"The predator population peak lags behind the prey population peak by approximately a quarter of a cycle ($\\approx 90^\\circ$ phase lag).","correct":true},{"text":"Both populations peak simultaneously at the exact same instant.","correct":false},{"text":"Predator and prey populations are in exact counter-phase ($180^\\circ$), with predators peaking at the prey minimum.","correct":false},{"text":"Both populations monotonically converge to zero within two generations.","correct":false}]'::jsonb, 'Coupled non-linear differential equations and phase lag in ecological oscillations.', 'Predators can only reproduce and expand after an abundance of prey food has already accumulated.', 1.8, 1.38, 0.25, 'International Biology Olympiad (IBO) / Cambridge STEP Mathematics', true),
  ('C04-ST-06', 4, '3-4', 'systemsThinking', 'olympiad', 'In electrical power grid stability, what is the ''duck curve'' phenomenon caused by high penetration of grid-scale solar photovoltaic generation?', '[{"text":"Midday net load plunges due to peak solar production, followed by a steep, rapid evening ramp demand as solar drops just as residential consumption spikes.","correct":true},{"text":"High voltage power lines attract migratory birds, causing physical line sagging.","correct":false},{"text":"Electricity travels in harmonic waves shaped like a duck bill.","correct":false},{"text":"Transformers overheat exclusively during sunrise.","correct":false}]'::jsonb, 'Grid net load transients, non-synchronous renewable generation, and evening ramp dispatch challenges.', 'Look at the shape of net electricity demanded from traditional power plants from noon to 7 PM.', 1.8, 1.54, 0.25, 'California ISO / European ENTSO-E Grid Engineering Challenge', true);
-- Batch for Class 5 (30 questions)
INSERT INTO public.scenarios (
  scenario_code, class_level, developmental_band, competency, difficulty,
  prompt, options, learning_objective, hint, irt_a, irt_b, irt_c,
  international_benchmark, is_active
) VALUES
  ('C05-SCI-01', 5, '5-6', 'scientificInquiry', 'standard', 'A student places two identical potted plants in identical soil. Plant A receives 100 mL of water in direct sunlight daily; Plant B receives 100 mL of water in a completely dark closet. After two weeks, Plant B has turned pale yellow and stretched unusually tall and thin. What does this experiment demonstrate?', '[{"text":"Plants need sunlight to synthesize chlorophyll and produce food through photosynthesis.","correct":true},{"text":"Plants grow healthier without light because darkness accelerates stem strength.","correct":false},{"text":"Water evaporates faster in darkness, suffocating the roots.","correct":false},{"text":"Sunlight prevents plant cells from dividing.","correct":false}]'::jsonb, 'Photosynthesis light dependency and etiolation.', 'Think about why chlorophyll gives plants their green color.', 1.45, -0.1499999999999999, 0.25, 'Singapore Primary Science Syllabus', true),
  ('C05-SCI-02', 5, '5-6', 'scientificInquiry', 'standard', 'Three identical liquid samples (A, B, and C) are poured into a clear graduated cylinder. Layer A sits at the bottom, Layer B floats in the middle, and Layer C floats on top. If a solid plastic bead with density 1.1 g/cm³ is dropped in, and it sinks through Layer C but floats on top of Layer B, what can you infer?', '[{"text":"Density of C < 1.1 g/cm³ < Density of B < Density of A.","correct":true},{"text":"Layer C has the greatest density because it is at the top.","correct":false},{"text":"The plastic bead dissolves the middle layer.","correct":false},{"text":"All three liquids have equal density because they are in the same cylinder.","correct":false}]'::jsonb, 'Fluid density layering / Joule heating & power dissipation / Quantum photoelectric energy threshold analysis.', 'Objects float in liquids that are more dense than themselves.', 1.3, 0.10000000000000009, 0.25, 'Singapore PSLE Science', true),
  ('C05-SCI-03', 5, '5-6', 'scientificInquiry', 'advanced', 'An experimenter drops a metal ball from heights of 1m, 2m, and 3m onto soft clay. The depth of the crater in the clay is 4mm, 8mm, and 12mm respectively. What is the independent variable and what physical quantity does crater depth measure?', '[{"text":"Independent variable: drop height; crater depth measures kinetic energy transferred to the clay.","correct":true},{"text":"Independent variable: crater depth; measured quantity is gravity.","correct":false},{"text":"Independent variable: clay softness; measured quantity is time.","correct":false},{"text":"Independent variable: ball mass; measured quantity is air friction.","correct":false}]'::jsonb, 'Identify experimental variables / Redox electrochemistry / Parallel nuclear decay kinematics.', 'The independent variable is what the experimenter intentionally manipulates.', 1.4, 0.8, 0.25, 'US NGSS Middle School PS3', true),
  ('C05-SCI-04', 5, '5-6', 'scientificInquiry', 'advanced', 'An optical bench tests refraction of light rays passing from medium 1 (index $n_1$) into medium 2 (index $n_2$). If the angle of incidence is $\theta_1 = 30^\circ$ and the refracted ray bends toward the normal line with $\theta_2 = 19.5^\circ$, what can be deduced about the optical density and wave speed?', '[{"text":"Medium 2 is optically denser ($n_2 > n_1$), and light propagates slower in medium 2 ($v_2 < v_1$).","correct":true},{"text":"Medium 2 is less dense, and light speed increases.","correct":false},{"text":"Light undergoes total internal reflection.","correct":false},{"text":"Light frequency decreases while wavelength remains constant.","correct":false}]'::jsonb, 'Snell’s Law, wave speed variance across refractive boundaries, and wave mechanics.', 'Bending toward the normal means light slows down.', 1.5, 0.95, 0.25, 'Cambridge IGCSE / Singapore O-Level Physics', true),
  ('C05-SCI-05', 5, '5-6', 'scientificInquiry', 'olympiad', 'Two pendulums have string lengths of 25 cm and 100 cm with identical bobs. If the 25 cm pendulum completes 20 full oscillations in 20 seconds, how many full oscillations will the 100 cm pendulum complete in the same 20 seconds?', '[{"text":"10 oscillations, because pendulum period is proportional to $\\sqrt{L}$, so doubling the period halves the frequency.","correct":true},{"text":"5 oscillations, because length is 4 times longer.","correct":false},{"text":"20 oscillations, because mass is identical.","correct":false},{"text":"40 oscillations, because longer strings swing faster.","correct":false}]'::jsonb, 'Non-linear proportionality in physical laws ($T \propto \sqrt{L}$ or $v_{\text{rms}} \propto \sqrt{T}$).', 'Notice the square root relationship.', 1.7, 1.4, 0.25, 'Chinese National Physics Olympiad / SASMO Junior', true),
  ('C05-SCI-06', 5, '5-6', 'scientificInquiry', 'olympiad', 'In a double-slit interference experiment with slit separation $d$ and screen distance $D$, light of wavelength $\lambda$ creates bright fringe spacing $\Delta y = \frac{\lambda D}{d}$. If the entire apparatus is immersed in water (refractive index $n = 1.33$), what happens to the fringe spacing?', '[{"text":"Fringe spacing decreases by a factor of 1.33 because the wavelength in water is $\\lambda / n$.","correct":true},{"text":"Fringe spacing increases by 1.33 because light speed decreases.","correct":false},{"text":"Fringes disappear completely due to total internal reflection.","correct":false},{"text":"Fringe spacing remains unchanged because frequency remains constant.","correct":false}]'::jsonb, 'Wave optics, wavelength reduction in refractive dielectric media, and interference fringe scaling.', 'In a medium with index n, speed and wavelength shrink by factor n, but frequency does not change.', 1.8, 1.6, 0.25, 'International Physics Olympiad (IPhO) / China Gaokao Physics', true),
  ('C05-CT-01', 5, '5-6', 'computationalThinking', 'standard', 'A rover on Mars receives a sequence of movement commands: [FORWARD 3, TURN_LEFT 90, FORWARD 2, TURN_RIGHT 90, BACKWARD 3]. What is the net straight-line displacement of the rover from its starting location?', '[{"text":"2 units to the left of the original position.","correct":true},{"text":"6 units forward.","correct":false},{"text":"Back at the exact starting location.","correct":false},{"text":"8 units diagonally.","correct":false}]'::jsonb, 'Coordinate tracking / Linear search worst-case analysis / Recursive state computation.', 'Follow the steps one by one.', 1.3, -0.09999999999999987, 0.25, 'European Bebras Challenge', true),
  ('C05-CT-02', 5, '5-6', 'computationalThinking', 'standard', 'A stack data structure follows Last-In, First-Out (LIFO). The operations executed are: PUSH(5), PUSH(8), PUSH(3), POP(), PUSH(12), POP(). What number is currently on the top of the stack?', '[{"text":"8","correct":true},{"text":"5","correct":false},{"text":"12","correct":false},{"text":"3","correct":false}]'::jsonb, 'Stack LIFO state transitions and memory frame tracking.', 'POP removes the item that was added most recently.', 1.4, 0.19999999999999996, 0.25, 'Bebras Computational Challenge / AP CS Principles', true),
  ('C05-CT-03', 5, '5-6', 'computationalThinking', 'advanced', 'You want to find an odd number between 1 and 100. Each question you ask can only be answered YES or NO. By always asking whether the number is greater than the middle of the remaining range, what is the maximum number of questions needed to find the exact number?', '[{"text":"6 questions, because $2^5 = 32 < 50 < 2^6 = 64$.","correct":true},{"text":"25 questions.","correct":false},{"text":"50 questions.","correct":false},{"text":"10 questions.","correct":false}]'::jsonb, 'Binary decision tree depth / Spanning tree edge minimization in graph theory.', 'Think about the minimum connections needed to prevent any node from being disconnected.', 1.5, 0.7999999999999999, 0.25, 'Bebras Intermediate / Singapore Computing', true),
  ('C05-CT-04', 5, '5-6', 'computationalThinking', 'advanced', 'In sorting algorithms, what distinguishes Bubble Sort ($O(n^2)$ average) from Merge Sort ($O(n \log n)$ average) on large lists of 100,000 items?', '[{"text":"Merge Sort uses divide-and-conquer recursion, executing in thousands of operations rather than billions.","correct":true},{"text":"Bubble Sort is faster because it does not require additional memory.","correct":false},{"text":"Both run in identical time because both compare elements in pairs.","correct":false},{"text":"Merge Sort only works on numbers, whereas Bubble Sort works on words.","correct":false}]'::jsonb, 'Asymptotic algorithmic growth rates ($O(n^2)$ vs $O(n \log n)$) at scale.', 'Calculate $(100,000)^2 = 10,000,000,000$ operations versus $100,000 \times 17 \approx 1,700,000$.', 1.6, 1.1, 0.25, 'USACO Bronze / Oxford Computing Challenge', true),
  ('C05-CT-05', 5, '5-6', 'computationalThinking', 'olympiad', 'A dynamic programming table solves the 0/1 Knapsack problem with capacity $W$ and $N$ items. If an iterative table stores state $dp[i][w]$, what does each cell value represent?', '[{"text":"The maximum achievable value using a subset of the first $i$ items with total weight at most $w$.","correct":true},{"text":"The remaining weight capacity after packing item $i$.","correct":false},{"text":"The total number of items included in the knapsack so far.","correct":false},{"text":"The ratio of value to weight for item $i$.","correct":false}]'::jsonb, 'Subproblem optimal substructure in Dynamic Programming.', 'The state stores the optimal objective value for a constrained capacity subproblem.', 1.8, 1.5, 0.25, 'International Olympiad in Informatics (IOI) / USACO Silver', true),
  ('C05-CT-06', 5, '5-6', 'computationalThinking', 'olympiad', 'A hash function maps keys into an array of size $M$. If two distinct keys $k_1 \ne k_2$ produce $h(k_1) = h(k_2)$, this is called a collision. Which strategy provides $O(1)$ expected lookup by appending colliding items to a linked list at that index?', '[{"text":"Separate Chaining","correct":true},{"text":"Linear Probing","correct":false},{"text":"Quadratic Probing","correct":false},{"text":"Double Hashing","correct":false}]'::jsonb, 'Hash table collision resolution architectures.', 'Look for the term that implies linking items in chains outside the primary array.', 1.7, 1.5, 0.25, 'China National Olympiad in Informatics (NOIP) Senior', true),
  ('C05-ED-01', 5, '5-6', 'engineeringDesign', 'standard', 'A team builds a toy crane. When lifting a heavy block, the crane tips over forward. Which design change will balance the crane effectively without reducing the load weight?', '[{"text":"Add a counterweight to the back of the crane arm and widen the base.","correct":true},{"text":"Make the crane arm twice as long.","correct":false},{"text":"Use thinner string for the hook.","correct":false},{"text":"Paint the crane bright yellow.","correct":false}]'::jsonb, 'Torque balance & center of gravity / Structural geometric rigidity / Thermal expansion tolerance in aerospace.', 'Think of a seesaw: how do you balance a heavy person?', 1.3, -0.10000000000000009, 0.25, 'US NGSS Engineering Design / Project Lead The Way', true),
  ('C05-ED-02', 5, '5-6', 'engineeringDesign', 'standard', 'An engineer designs a solar-powered water pump for an off-grid farm. The pump requires 500W of power. If the solar panels have an efficiency of 20% and peak sunlight intensity is 1,000 W/m², what is the MINIMUM solar collector surface area required?', '[{"text":"2.5 square meters ($1000 \\times 0.20 = 200\\text{ W/m}^2$; $500 / 200 = 2.5\\text{ m}^2$).","correct":true},{"text":"1.0 square meters.","correct":false},{"text":"5.0 square meters.","correct":false},{"text":"10.0 square meters.","correct":false}]'::jsonb, 'Solar energy conversion efficiency and collector area sizing.', 'Calculate usable electrical power per square meter first.', 1.4, 0.29999999999999993, 0.25, 'European Clean Energy Engineering Curriculum / NGSS HS-ETS1', true),
  ('C05-ED-03', 5, '5-6', 'engineeringDesign', 'advanced', 'A bicycle braking system uses hydraulic disc calipers. The master cylinder at the brake lever has a piston area of 1 cm², while the slave caliper piston at the wheel has an area of 4 cm². If the rider applies a force of 50 N to the master cylinder, what clamping force does the slave cylinder exert on the brake rotor (assuming no fluid friction)?', '[{"text":"200 N, because Pascal''s Principle transmits equal pressure: $F_2 = F_1 \\times (A_2 / A_1)$.","correct":true},{"text":"50 N, because force cannot multiply in closed fluids.","correct":false},{"text":"12.5 N, because area expanded.","correct":false},{"text":"800 N, because area is squared.","correct":false}]'::jsonb, 'Pascal’s Principle, hydraulic mechanical advantage, and fluid power transmission.', 'Pressure $P = F/A$ is uniform throughout the connected hydraulic fluid.', 1.5, 0.7999999999999999, 0.25, 'German Dual Vocational Mechatronics / US Project Lead The Way', true),
  ('C05-ED-04', 5, '5-6', 'engineeringDesign', 'advanced', 'In autonomous electric vehicles, why do battery management systems (BMS) implement active cell balancing during charging cycles?', '[{"text":"To prevent individual cells with slightly lower capacity from overcharging or deep-discharging, which causes thermal runaway and premature pack degradation.","correct":true},{"text":"To make the vehicle accelerate twice as fast at low battery levels.","correct":false},{"text":"To convert alternating current directly into radio signals.","correct":false},{"text":"To eliminate the need for an electric motor.","correct":false}]'::jsonb, 'Lithium-ion electrochemical cell degradation, thermal safety, and state-of-charge management.', 'A battery pack is only as strong as its weakest cell.', 1.6, 1.05, 0.25, 'MIT Engineering NEET / Singapore A-Level Engineering Science', true),
  ('C05-ED-05', 5, '5-6', 'engineeringDesign', 'olympiad', 'A structural cantilever beam of length $L$ carries a concentrated end load $P$. If both the width $b$ and depth $h$ of its rectangular cross-section are doubled ($2b, 2h$), by what factor does the maximum tip deflection $\delta = \frac{PL^3}{3EI}$ decrease (where moment of inertia $I = \frac{bh^3}{12}$)?', '[{"text":"Deflection decreases by a factor of 16 (it becomes $1/16$ of original deflection).","correct":true},{"text":"Deflection decreases by a factor of 4.","correct":false},{"text":"Deflection decreases by a factor of 8.","correct":false},{"text":"Deflection decreases by a factor of 2.","correct":false}]'::jsonb, 'Beam deflection formulas, second moment of area, and structural scale geometry.', 'Calculate how $I = \frac{b h^3}{12}$ scales when $b \to 2b$ and $h \to 2h$: $I'' = (2b)(2h)^3 = 16 I$.', 1.8, 1.4, 0.25, 'China National Collegiate / Senior High Engineering Mechanics Challenge', true),
  ('C05-ED-06', 5, '5-6', 'engineeringDesign', 'olympiad', 'In designing an unmanned quadcopter drone, flight endurance is limited by the specific energy of the battery. If an engineer replaces a 1 kg lithium-ion battery (250 Wh/kg) with a 1 kg solid-state battery (500 Wh/kg), why does flight time MORE than double in real atmospheric conditions?', '[{"text":"The total payload mass remains identical, meaning aerodynamic hover power required remains constant while available energy doubles, enabling continuous optimal motor efficiency.","correct":true},{"text":"Solid-state batteries produce negative gravity.","correct":false},{"text":"Propellers spin at infinite velocity when powered by solid-state chemistry.","correct":false},{"text":"Air resistance drops to zero.","correct":false}]'::jsonb, 'Hover aerodynamics, power-to-weight endurance scaling, and battery specific energy limits.', 'Notice that the battery weight did not change, so the drone does not need extra lift power to stay aloft.', 1.8, 1.6500000000000001, 0.25, 'FIRST Robotics World Championship / Singapore DSTA Engineering', true),
  ('C05-MR-01', 5, '5-6', 'mathematicalReasoning', 'standard', 'In a parking lot, there are 20 vehicles consisting of bicycles (2 wheels each) and cars (4 wheels each). If there are 64 wheels in total, how many cars are parked in the lot?', '[{"text":"12 cars (and 8 bicycles).","correct":true},{"text":"10 cars.","correct":false},{"text":"14 cars.","correct":false},{"text":"16 cars.","correct":false}]'::jsonb, 'Assumption heuristic / Difference of squares factorization / Logarithmic equations with domain constraints.', 'Assume all 20 vehicles were bicycles: that would be 40 wheels. Each car adds 2 extra wheels.', 1.4, -0.19999999999999996, 0.25, 'Singapore Math (Bar Models / Heuristics) / SASMO', true),
  ('C05-MR-02', 5, '5-6', 'mathematicalReasoning', 'standard', 'A circle of radius 6 cm is inscribed inside an equilateral triangle. What is the area of the equilateral triangle?', '[{"text":"$108\\sqrt{3}\\text{ cm}^2$","correct":true},{"text":"$72\\sqrt{3}\\text{ cm}^2$","correct":false},{"text":"$144\\text{ cm}^2$","correct":false},{"text":"$36\\pi\\text{ cm}^2$","correct":false}]'::jsonb, 'Incircle geometry of regular polygons and trigonometric relationship with altitude.', 'In an equilateral triangle, inradius $r = h/3$. If $r=6$, altitude $h=18$, side $s = 18 / (\sqrt{3}/2) = 12\sqrt{3}$.', 1.5, 0.45000000000000007, 0.25, 'Kangaroo Math Student / AMC 8', true),
  ('C05-MR-03', 5, '5-6', 'mathematicalReasoning', 'advanced', 'How many three-digit positive integers are divisible by both 4 and 6?', '[{"text":"75 integers (multiples of $\\text{LCM}(4,6)=12$ between 100 and 999).","correct":true},{"text":"150 integers.","correct":false},{"text":"83 integers.","correct":false},{"text":"90 integers.","correct":false}]'::jsonb, 'LCM arithmetic arithmetic progression counting / Vieta’s formulas.', 'Use the relationship $(r_1 - r_2)^2 = (r_1 + r_2)^2 - 4r_1 r_2$.', 1.6, 0.9, 0.25, 'American Mathematics Competitions (AMC 8/10)', true),
  ('C05-MR-04', 5, '5-6', 'mathematicalReasoning', 'advanced', 'How many distinct permutations can be formed from the letters in the word ''PARALLEL''?', '[{"text":"3,360 permutations ($\\frac{8!}{3! \\times 2!} = \\frac{40,320}{6 \\times 2} = 3,360$).","correct":true},{"text":"40,320 permutations.","correct":false},{"text":"6,720 permutations.","correct":false},{"text":"1,680 permutations.","correct":false}]'::jsonb, 'Multinomial permutations with repeated elements.', 'Count the repetitions: 3 Ls, 2 As in an 8-letter word.', 1.6, 1.15, 0.25, 'China High School Mathematics League / AMC 10', true),
  ('C05-MR-05', 5, '5-6', 'mathematicalReasoning', 'olympiad', 'What is the remainder when $3^{2026}$ is divided by 7?', '[{"text":"2, because by Fermat''s Little Theorem $3^6 \\equiv 1 \\pmod 7$, and $2026 = 6 \\times 337 + 4$, so $3^4 = 81 \\equiv 4 \\pmod 7$ (or 2).","correct":true},{"text":"1","correct":false},{"text":"4","correct":false},{"text":"6","correct":false}]'::jsonb, 'Fermat’s Little Theorem and modular exponentiation cycles.', 'Compute the powers of 3 modulo 7: 3, 9=2, 6, 18=4, 12=5, 15=1 (cycle of length 6).', 1.8, 1.55, 0.25, 'Chinese Mathematical Olympiad (CMO) / Singapore SMO', true),
  ('C05-MR-06', 5, '5-6', 'mathematicalReasoning', 'olympiad', 'Consider the infinite geometric series $S = 1 + 2x + 3x^2 + 4x^3 + \dots$ for $|x| < 1$. What is the closed-form algebraic sum of this arithmetico-geometric series?', '[{"text":"$\\frac{1}{(1-x)^2}$","correct":true},{"text":"$\\frac{1}{1-x}$","correct":false},{"text":"$\\frac{x}{(1-x)^2}$","correct":false},{"text":"$\\frac{1}{1-x^2}$","correct":false}]'::jsonb, 'Summation of arithmetico-geometric series via perturbation or derivative of geometric series.', 'Notice that $\frac{d}{dx}\left(\frac{1}{1-x}\right) = \frac{d}{dx}(1+x+x^2+x^3+\dots) = 1+2x+3x^2+\dots$.', 1.8, 1.75, 0.25, 'Putnam / AMC 12 / IIT-JEE Advanced', true),
  ('C05-ST-01', 5, '5-6', 'systemsThinking', 'standard', 'In an agricultural valley, farmers spray a chemical that kills 95% of caterpillars eating cabbage. Six weeks later, cabbage yield is worse than before because the birds that ate caterpillars migrated away, and aphid pests (which caterpillars kept in check) multiplied unchecked. What systems principle does this illustrate?', '[{"text":"Unintended consequences in an interconnected ecosystem: eliminating one component triggers second-order cascades.","correct":true},{"text":"Pesticides make soil toxic to sunlight.","correct":false},{"text":"Birds eat cabbage directly when caterpillars are absent.","correct":false},{"text":"Caterpillars protect plants from rain.","correct":false}]'::jsonb, 'Second-order effects in ecological food webs / Resource contention in shared flow networks / Control loop phase margin & resonance.', 'Look beyond the immediate action to the downstream ripple effects.', 1.3, -0.050000000000000044, 0.25, 'OECD PISA Systems Thinking Framework', true),
  ('C05-ST-02', 5, '5-6', 'systemsThinking', 'standard', 'A logistics company observes the ''Bullwhip Effect'': a small 5% spike in consumer retail demand for toilet paper causes a 15% order increase to wholesalers, and a 40% order surge to paper manufacturers. What is the root systemic cause of this amplification?', '[{"text":"Information distortion, safety-stock buffering, and lack of real-time supply chain transparency across sequential tiers.","correct":true},{"text":"Paper mills intentionally slow production to raise prices.","correct":false},{"text":"Trucks travel slower when carrying larger loads.","correct":false},{"text":"Consumers buy paper only on weekends.","correct":false}]'::jsonb, 'The Bullwhip Effect in multi-echelon supply networks and order variance propagation.', 'Each tier adds extra buffer stock because they cannot directly see final consumer demand.', 1.4, 0.3999999999999999, 0.25, 'MIT System Dynamics in K-12 / AP Macroeconomics', true),
  ('C05-ST-03', 5, '5-6', 'systemsThinking', 'advanced', 'In climate science, the ice-albedo feedback is a classic example of which systemic loop dynamic?', '[{"text":"A reinforcing (positive) feedback loop: warming melts reflective ice, revealing dark ocean that absorbs more heat and accelerates warming.","correct":true},{"text":"A balancing (negative) feedback loop that automatically cools the planet back to baseline.","correct":false},{"text":"An isolated thermodynamic open loop with zero feedback.","correct":false},{"text":"A linear cause-and-effect with static equilibrium.","correct":false}]'::jsonb, 'Reinforcing feedback mechanisms in non-linear planetary climate systems.', 'Does the effect amplify the original cause (positive) or counteract it (negative)?', 1.5, 0.8, 0.25, 'European Matura Environmental Systems / PISA 2025', true),
  ('C05-ST-04', 5, '5-6', 'systemsThinking', 'advanced', 'When a city adds 3 new highway lanes to relieve severe traffic congestion, commute times initially drop for 3 months, but return to severe gridlock 18 months later (Braess''s Paradox / Induced Demand). Why does expanding capacity fail to solve the congestion?', '[{"text":"Induced demand: reduced travel friction incentivizes public transit riders and distant commuters to drive, filling new capacity until congestion equilibrium restores.","correct":true},{"text":"Cars travel slower on wider highways due to optical illusions.","correct":false},{"text":"The city traffic lights automatically turn red more frequently.","correct":false},{"text":"Highway asphalt expands in sunlight, narrowing the lanes.","correct":false}]'::jsonb, 'Induced demand, feedback elasticity, and unintended policy equilibrium in urban transport networks.', 'Think about how lowering the perceived cost of an activity changes consumer behavior.', 1.6, 1.1, 0.25, 'OECD Urban Mobility Systems / Harvard Policy Systems', true),
  ('C05-ST-05', 5, '5-6', 'systemsThinking', 'olympiad', 'In predator-prey dynamics modeled by the Lotka-Volterra differential equations ($\frac{dx}{dt} = \alpha x - \beta x y$, $\frac{dy}{dt} = \delta x y - \gamma y$), what phase relationship exists between prey population peaks ($x$) and predator population peaks ($y$)?', '[{"text":"The predator population peak lags behind the prey population peak by approximately a quarter of a cycle ($\\approx 90^\\circ$ phase lag).","correct":true},{"text":"Both populations peak simultaneously at the exact same instant.","correct":false},{"text":"Predator and prey populations are in exact counter-phase ($180^\\circ$), with predators peaking at the prey minimum.","correct":false},{"text":"Both populations monotonically converge to zero within two generations.","correct":false}]'::jsonb, 'Coupled non-linear differential equations and phase lag in ecological oscillations.', 'Predators can only reproduce and expand after an abundance of prey food has already accumulated.', 1.8, 1.5, 0.25, 'International Biology Olympiad (IBO) / Cambridge STEP Mathematics', true),
  ('C05-ST-06', 5, '5-6', 'systemsThinking', 'olympiad', 'In electrical power grid stability, what is the ''duck curve'' phenomenon caused by high penetration of grid-scale solar photovoltaic generation?', '[{"text":"Midday net load plunges due to peak solar production, followed by a steep, rapid evening ramp demand as solar drops just as residential consumption spikes.","correct":true},{"text":"High voltage power lines attract migratory birds, causing physical line sagging.","correct":false},{"text":"Electricity travels in harmonic waves shaped like a duck bill.","correct":false},{"text":"Transformers overheat exclusively during sunrise.","correct":false}]'::jsonb, 'Grid net load transients, non-synchronous renewable generation, and evening ramp dispatch challenges.', 'Look at the shape of net electricity demanded from traditional power plants from noon to 7 PM.', 1.8, 1.6500000000000001, 0.25, 'California ISO / European ENTSO-E Grid Engineering Challenge', true);
